from collections import OrderedDict


class TTLCache:
    def __init__(self, capacity: int, ttl: float, clock):
        self.capacity = capacity
        self.ttl = ttl
        self.clock = clock
        self._data = OrderedDict()          # key -> (value, expiry)
        self.hits = 0
        self.misses = 0
        self.evictions = 0
        self.expirations = 0

    def _now(self):
        return self.clock()

    def _purge_expired(self):
        now = self._now()
        expired = [k for k, (_, exp) in self._data.items() if now >= exp]
        for k in expired:
            del self._data[k]
            self.expirations += 1

    def put(self, key, value):
        if self.capacity <= 0:
            return
        now = self._now()
        if key in self._data:
            # replace existing key
            self._data[key] = (value, now + self.ttl)
            self._data.move_to_end(key)
            return

        # new key
        if len(self._data) >= self.capacity:
            self._purge_expired()
            if len(self._data) >= self.capacity:
                self._data.popitem(last=False)
                self.evictions += 1

        self._data[key] = (value, now + self.ttl)

    def get(self, key, default=None):
        if self.capacity <= 0:
            self.misses += 1
            return default
        now = self._now()
        if key in self._data:
            val, exp = self._data[key]
            if now >= exp:
                del self._data[key]
                self.expirations += 1
                self.misses += 1
                return default
            self.hits += 1
            self._data.move_to_end(key)
            return val
        self.misses += 1
        return default

    def __len__(self):
        now = self._now()
        cnt = 0
        for _, (_, exp) in self._data.items():
            if now < exp:
                cnt += 1
        return cnt

    def stats(self):
        return {
            "hits": self.hits,
            "misses": self.misses,
            "evictions": self.evictions,
            "expirations": self.expirations,
        }
