def parse_duration(s: str) -> int:
    t = s.strip()
    if not t:
        raise ValueError("empty duration")

    n = len(t)
    i = 0
    values = {}
    last_idx = -1
    unit_to_idx = {"h": 0, "m": 1, "s": 2}

    while i < n:
        while i < n and t[i].isspace():
            i += 1
        if i >= n:
            break

        start = i
        while i < n and t[i].isdigit():
            i += 1
        if start == i:
            raise ValueError("number expected")
        num_str = t[start:i]
        # int conversion also rejects empty / too large? Python handles
        num = int(num_str)

        if i >= n:
            raise ValueError("unit expected")
        unit_char = t[i]
        i += 1
        if not unit_char.isalpha():
            raise ValueError("unit expected")
        unit = unit_char.lower()
        if unit not in unit_to_idx:
            raise ValueError(f"unknown unit {unit_char}")

        idx = unit_to_idx[unit]
        if unit in values:
            raise ValueError("repeated unit")
        if idx <= last_idx:
            raise ValueError("units out of order")

        values[unit] = num
        last_idx = idx

    total = 0
    total += values.get("h", 0) * 3600
    total += values.get("m", 0) * 60
    total += values.get("s", 0)
    return total
