def summarize_ranges(nums: list[int]) -> str:
    if not nums:
        return ""
    arr = sorted(set(nums))
    parts = []
    i = 0
    n = len(arr)
    while i < n:
        start = arr[i]
        j = i
        while j + 1 < n and arr[j + 1] == arr[j] + 1:
            j += 1
        run_len = j - i + 1
        if run_len >= 3:
            parts.append(f"{start}..{arr[j]}")
        else:
            parts.extend(str(arr[k]) for k in range(i, j + 1))
        i = j + 1
    return ",".join(parts)
