import re
from typing import List, Tuple, Dict

def top_customers(rows: list[dict], n: int) -> list[tuple[str, float]]:
    data: Dict[str, list] = {}  # key -> [display_name, total]

    for row in rows:
        if not isinstance(row, dict):
            continue

        raw_name = row.get("customer")
        if raw_name is None:
            continue
        name = str(raw_name).strip()
        if not name:
            continue
        key = name.lower()

        raw_amount = row.get("amount")
        if raw_amount is None:
            continue
        amt_str = str(raw_amount)

        cleaned = re.sub(r"[^0-9\.\-]", "", amt_str)
        if not cleaned or cleaned in ("-", ".", "-.", ".-"):
            continue
        try:
            amt = float(cleaned)
        except ValueError:
            continue

        if key not in data:
            data[key] = [name, 0.0]
        data[key][1] += amt

    items: List[Tuple[str, float]] = []
    for display_name, total in data.values():
        total_rounded = round(total, 2)
        items.append((display_name, total_rounded))

    items.sort(key=lambda x: (-x[1], x[0]))
    if n < 0:
        return []
    return items[:n]
